# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_par_a import P,R,G
W=[
E('peer','英 /pɪə/；美 /pɪr/','同辈、同等者；贵族；另有“仔细看”的动词','这里先想与你处在相近位置的人：同龄、同级，或同专业的人。','名词经古法语 per／peir 来自拉丁 par“相等”。动词 peer“费力地看、凝视”来源不同，不能从同辈义推出来。',R,'peer pressure 是同伴压力；peer review 是让同领域的人评审。peer 不一定是朋友，也不一定严格同龄，关键是相关语境里地位或角色相近。英国贵族称谓中的 peer 也有历史上的同等级背景。', 'a peer group；peer pressure；peer review；one’s peers。','colleague 是同事，peer 是相关层面上的同等者，两者可重合但不完全相同。peer through the window 的 peer 是另源动词。',('She is respected by her peers in the field.','她受到这个领域同行的尊重。'),('The study was reviewed by a group of independent peers.','这项研究由一组独立同行进行了评审。'),('He peered through the window to see who was inside.','他透过窗户仔细看，想弄清里面是谁。'),sources=['https://www.etymonline.com/word/peer','https://en.wiktionary.org/wiki/peer']),
E('peerless','英 /ˈpɪələs/；美 /ˈpɪrləs/','无与伦比的；无人能及的','peer 是能与你并列的人，-less 说找不到这样的对手。','peer“同等者” + -less“没有”；与 peer“凝视”的动词无关。',R+[['peer + -less → peerless','没有可以匹敌的人或物']],'peerless 是强烈赞美，常夸技艺、成就或品质。它不是“没有朋友”或“没有同伴”的普通生活状态，而是在某个方面无人能比。正式介绍中用它，等于作了很高的评价。','a peerless musician；peerless craftsmanship；peerless skill。','peerless 接近 unrivalled、incomparable；lonely 是孤独，不表达能力无人能比。',('The exhibition celebrates her peerless craftsmanship.','这次展览赞颂她无人能及的工艺。'),('Fans describe him as a peerless storyteller.','喜爱他的人称他为无与伦比的讲故事高手。'),sources=['https://en.wiktionary.org/wiki/peerless','https://www.etymonline.com/word/peerless']),
E('pair','英 /peə/；美 /per/','一对、一双；配对','两个相配的东西被看成一组，就像左右鞋搭在一起。','经法语 paire 来自拉丁 paria“相等的东西”，后者是 par 的中性复数形式。',P+[['拉丁 paria → 法语 paire','相配的一组东西'],['英语 pair','一对；组成一对']],'a pair of shoes 是两只鞋组成的一双。a pair of scissors 虽是一把剪刀，也按两个配合部分来称呼。作动词时 pair students 是给学生分组配对，不要求两个人完全相同，而是让他们组成一个合作单位。','a pair of shoes；work in pairs；pair A with B；pair up。','pair 明确强调成对；couple 可以说两个人或大约两三个，具体用法不同。pair 与 pear“梨”同音但不同源。',('I found a pair of gloves under the bench.','我在长椅下面发现了一副手套。'),('The teacher paired each beginner with a more experienced student.','老师让每位初学者与一位更有经验的学生结成一组。'),sources=['https://www.etymonline.com/word/pair','https://en.wiktionary.org/wiki/pair']),
E('disparity','/dɪˈspærəti/','明显差距；不平等、不相称','两边放在一起，发现不在同一水平线上，而且差距值得注意。','经法语 disparité 来自拉丁不相等相关形式；可联系 dis-“不” + par“相等”，现代看作 dis- + parity 便于记忆。',P+[['拉丁 dispar／disparitas → 法语 disparité','不相等；不平等状态'],['英语 disparity','差距、不平等']],'income disparity 是收入差距；a disparity between promise and reality 是承诺与现实不相称。它比普通 difference 更容易让人想到数量、待遇或条件上的明显差距，但是否不公还要看具体论述。','a disparity between A and B；income disparities；reduce disparities。','difference 泛指不同，disparity 常强调不相等或不相称；parity 则是同等水平。',('The report highlights a large disparity in access to public transport.','报告指出，人们使用公共交通的便利程度存在很大差距。'),('There is a clear disparity between the promised service and what customers receive.','承诺的服务与顾客实际得到的服务明显不相称。'),sources=['https://www.etymonline.com/word/disparity','https://en.wiktionary.org/wiki/disparity']),
E('disparage','/dɪˈspærɪdʒ/','贬低；轻视、贬损','用言语把别人或别人的成果往下压，说得不值得尊重。','经古法语 desparagier，包含 des- 与 parage“门第、地位”；与 par“同等”相关。不要把末尾 age 拆成“年龄”。',G,'disparage 的早期背景涉及等级和婚姻观念，今天常指贬损价值。说 someone disparaged my work，重点不只是他不同意，而是他把我的工作说得很不值一提。这种“往下压”的态度比意见分歧更关键。','disparage someone’s work；disparage an achievement；disparage a rival。','criticize 可以是提出有根据的批评；disparage 带轻视、压低价值的意味。不同意某人不一定是 disparage。',('You can disagree with her without disparaging her experience.','你可以不同意她，但不必贬低她的经验。'),('He tried to disparage the team’s achievement as mere luck.','他试图把团队的成就贬低成不过是运气。'),sources=['https://www.etymonline.com/word/disparage','https://en.wiktionary.org/wiki/disparage']),
E('disparaging','/dɪˈspærɪdʒɪŋ/','贬低人的；轻蔑的','不是认真讨论哪里有问题，而是话里透出“根本不怎么样”。','disparage 去 e + -ing；由动作的分词发展为形容这种态度的词。',G+[['disparage + -ing → disparaging','带贬损、轻视意味的']],'a disparaging remark 是贬损的话；a disparaging tone 是轻蔑的口气。它可以通过措辞，也可以通过语气表达，不必包含明显的脏话。判断时看是否在降低对方的价值或地位。','disparaging remarks；a disparaging comment about；a disparaging tone。','disparaging 描述话语或态度；disparaged 描述受到贬低。两者不要只按“都是形容词”混用。',('She objected to his disparaging remarks about the volunteers.','她反对他那些贬低志愿者的话。'),('The article uses a disparaging tone when discussing local artists.','文章谈到当地艺术家时用了轻蔑的语气。'),sources=['https://en.wiktionary.org/wiki/disparaging','https://www.etymonline.com/word/disparage']),
E('disparagement','/dɪˈspærɪdʒmənt/','贬损；轻视性评论','把贬低别人这件事，当成一种行为或一段评论来谈。','经古法语 desparagement 借入；现代可联系 disparage + -ment。',P+[['古法语 desparagier → desparagement','贬低 → 贬低行为'],['英语 disparagement','贬损、轻视性言论']],'disparagement 常出现在较正式的写作里。a response without disparagement 是回应对方时不贬损人格或价值。它把注意力放在交流方式：你是否通过踩低别人来表达自己的观点。','personal disparagement；disparagement of someone；without disparagement。','disagreement 是意见不同，disparagement 是贬低；可以有前者而没有后者。',('The discussion should allow criticism without personal disparagement.','讨论应允许批评，同时避免对个人的贬损。'),('Her reply contained no disparagement of the opposing team.','她的回应没有任何贬低对方团队的话。'),sources=['https://www.etymonline.com/word/disparagement','https://en.wiktionary.org/wiki/disparagement']),
]
